var n=`0172-osso-buco`;var a=`world-0172`;var i=`IT`;var s=`southern-europe`;var o=4;var l=127;var r={en:`Osso Buco`,ua:`Оссобуко`};var u={en:`A classic dish from Italy, featuring veal shank, yellow onion, carrot, celery stalk. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Італія. Основні складники: теляча гомілка, жовта цибуля, морква, стебло селери. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var g=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 10 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 10 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:10,i:[[`veal-shank`,1050,`g`],[`all-purpose-flour`,65,`g`],[`unsalted-butter`,55,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`yellow-onion`,150,`g`],[`carrot`,110,`g`],[`celery-stalk`,100,`g`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 105 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 105 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:105,i:[[`dry-white-wine`,200,`ml`],[`beef-stock`,470,`ml`],[`tomato`,150,`g`],[`bay-leaf`,1,`leaf`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`lemon-zest`,8,`g`],[`garlic`,2,`clove`],[`parsley`,25,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]}];var d={slug:n,id:a,country:`IT`,region:s,servings:4,minutes:127,title:r,text:u,steps:g};export{i as country,d as default,a as id,l as minutes,s as region,o as servings,n as slug,g as steps,u as text,r as title};